import {initializeAnalytics} from './analytics.js';
import {STUDIES} from './atlas/catalog.js';
import {mountThemePicker} from './theme.js';
import {mountTechReels} from './tech-reels.js';
const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';
const x='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg>';
const pages=[['home','Home','index.html'],['work','Work','work.html'],['lab','Lab','lab.html'],['atlas','Atlas','atlas.html'],['about','About','about.html']];
const page=document.body.dataset.page||'home';
const defaults={name:'Sub',role:'Support Engineer · Datacenter Tech',email:'',domain:'5u8han.dev'};
function getProfile(){try{const p=JSON.parse(localStorage.getItem('portfolio-profile')||'null');return p&&typeof p==='object'?{...defaults,...Object.fromEntries(Object.entries(p).filter(([k,v])=>['name','role','email'].includes(k)&&typeof v==='string'))}:defaults}catch{return defaults}}
let profile=getProfile();
const brand='<span class="brand-x" aria-hidden="true">✳</span>5u8han<span class="domain-dev">.dev</span>';
document.querySelector('#site-header').innerHTML=`<a class="skip-link" href="#main">Skip to content</a><div class="container"><div class="main-header"><a class="wordmark" href="index.html" aria-label="Sub home">${brand}</a><nav class="desktop-nav" aria-label="Main">${pages.map(([id,label,url],i)=>`<a href="${url}"${id===page?' aria-current="page"':''}><span class="nav-index">0${i+1}</span>${label}</a>`).join('')}</nav><div class="header-actions"><button class="icon-btn search-trigger" id="command-trigger" aria-label="Search pages" aria-haspopup="dialog"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg></button><button class="icon-btn" id="motion-toggle" type="button" aria-label="Turn off decorative motion" aria-pressed="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m3 6 6 6-6 6m7-12 6 6-6 6m10-12v12"/></svg></button><button class="menu-button" id="menu-trigger" type="button" aria-haspopup="dialog">Menu <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 8h18M3 16h18"/></svg></button></div></div></div>`;
document.querySelector('#site-footer').innerHTML=`<div class="footer-base studio-footer"><div class="container"><div class="studio-footer-word display">THERE’S ALWAYS<br><span>ANOTHER LAYER.</span></div><div class="footer-main"><div><a class="wordmark" href="index.html">${brand}</a><p>Support engineering · Datacenter technology<br>Chicago, Illinois</p></div><nav class="footer-links" aria-label="Footer">${pages.map(([,label,url])=>`<a href="${url}">${label}</a>`).join('')}<a href="reference.html">Source workbench</a></nav></div><div class="studio-socials"><a href="mailto:info@5u8han.dev">info@5u8han.dev</a><a href="https://github.com/5u8han" rel="me">GitHub ↗</a><a href="https://www.linkedin.com/in/5u8han" rel="me">LinkedIn ↗</a><a href="https://twitter.com/5u8han" rel="me">Twitter / X ↗</a><button type="button" data-privacy-open>Privacy / analytics</button></div><div class="footer-meta"><span>© 2026 SUB / 5U8HAN.DEV</span><span>THE WIDE VIEW. THE FINE DETAIL.</span><span>Illustrated systems. Real experience.</span></div></div></div>`;
function syncProfile(){document.querySelectorAll('[data-profile]').forEach(el=>{const field=el.dataset.profile;if(typeof profile[field]==='string')el.textContent=profile[field]});const email=profile.email?.trim();const validEmail=email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);document.querySelectorAll('.header-contact,.footer-round').forEach(a=>{a.href=validEmail?'mailto:'+encodeURIComponent(email):'about.html#correspondence';a.setAttribute('aria-label',validEmail?'Email '+profile.name:'Connect with '+profile.name)})}
window.addEventListener('portfolio:profilechange',event=>{profile={...defaults,...event.detail};syncProfile()});syncProfile();

const reduce=matchMedia('(prefers-reduced-motion: reduce)');
let preference=true;try{preference=localStorage.getItem('portfolio-motion')!=='off'}catch{}
const motionEnabled=()=>preference&&!reduce.matches;
function syncMotion(){const enabled=motionEnabled();document.documentElement.dataset.motion=enabled?'on':'off';const b=document.querySelector('#motion-toggle');b.setAttribute('aria-pressed',String(enabled));b.setAttribute('aria-label',reduce.matches?'Motion is off: system reduced motion is active':enabled?'Turn off decorative motion':'Turn on decorative motion');window.dispatchEvent(new CustomEvent('portfolio:motionchange',{detail:{enabled}}))}
document.querySelector('#motion-toggle').addEventListener('click',()=>{if(reduce.matches){toast('Motion follows your system’s reduced-motion preference.');return}preference=!preference;try{localStorage.setItem('portfolio-motion',preference?'on':'off')}catch{}syncMotion();toast(preference?'Motion on. You’re in control.':'A quieter view. Motion is off.')});reduce.addEventListener('change',syncMotion);
window.PortfolioLab={motionEnabled,getProfile:()=>profile,toast};syncMotion();

const menu=document.createElement('dialog');menu.className='menu-dialog';menu.setAttribute('aria-labelledby','menu-title');menu.innerHTML=`<div class="menu-content"><div class="menu-top"><h2 class="micro" id="menu-title">Choose your direction.</h2><button class="icon-btn" aria-label="Close menu">${x}</button></div><nav class="menu-links" aria-label="Expanded navigation">${pages.map(([,label,url],i)=>`<a href="${url}"><span>0${i+1}</span>${label}<span aria-hidden="true">↗</span></a>`).join('')}</nav><p class="menu-caption">From board-level detail to infrastructure-wide thinking. A portfolio of support, systems and experimentation.</p><div class="menu-bottom"><span class="live-dot"></span>Sub / Chicago, IL / 5u8han.dev</div></div>`;document.body.append(menu);
let menuAnimation;
document.querySelector('#menu-trigger').addEventListener('click',()=>{menu.showModal();if(motionEnabled()&&window.gsap){menuAnimation=window.gsap.fromTo(menu.querySelectorAll('.menu-links a'),{y:22,opacity:.5},{y:0,opacity:1,duration:.45,stagger:.045,ease:'power3.out'})}});
menu.querySelector('button').addEventListener('click',()=>menu.close());menu.addEventListener('close',()=>{menuAnimation?.kill();menu.querySelectorAll('.menu-links a').forEach(a=>{a.style.removeProperty('transform');a.style.removeProperty('opacity')})});

const commands=[['Home','index.html','The introduction'],['Selected work','work.html','Infrastructure / networks / repair'],['Motion & signal lab','lab.html','Animation / 3D / audio'],['Motion atlas','atlas.html','20 original interactive art studies'],['About Sub','about.html','Experience & approach'],['Skills inventory','reference.html#inventory','Every retained source'],['Datacenter concepts','concepts.html','Three animated landing worlds'],['Correspondence','about.html#correspondence','A quiet place for a note'],...STUDIES.map(study=>[study.title,'atlas/'+study.slug+'.html',study.family+' / '+study.tags.join(' / ')])];
const command=document.createElement('dialog');command.className='command-dialog';command.setAttribute('aria-label','Search pages');command.innerHTML=`<div class="command-heading"><label class="sr-only" for="command-search">Find a page or experiment</label><input id="command-search" placeholder="Find a page or experiment…" autocomplete="off"><button class="icon-btn" aria-label="Close page search">${x}</button></div><nav class="command-results" aria-label="Search results"></nav><p class="command-empty" hidden>No matching page. Try “work”, “lab” or “skills”.</p><p class="command-note">Tab to explore · Enter to open · Esc to close · Ctrl / ⌘ K to search</p>`;document.body.append(command);
function filterCommands(){const q=command.querySelector('input').value.toLowerCase().trim();const matches=commands.filter(row=>row.join(' ').toLowerCase().includes(q));const list=command.querySelector('nav');list.replaceChildren();for(const [label,url,detail] of matches){const a=document.createElement('a');a.href=url;const name=document.createTextNode(label);const small=document.createElement('span');small.textContent=detail;a.append(name,small);list.append(a)}command.querySelector('.command-empty').hidden=matches.length>0}
filterCommands();function openSearch(){if(menu.open)menu.close();if(command.open)return;command.showModal();command.querySelector('input').focus()}
document.querySelector('#command-trigger').addEventListener('click',openSearch);command.querySelector('button').addEventListener('click',()=>command.close());command.querySelector('input').addEventListener('input',filterCommands);command.querySelector('input').addEventListener('keydown',event=>{if(event.key==='Enter'){const first=command.querySelector('nav a');if(first)first.click()}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch()}});
for(const dialog of [menu,command])dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()});
let toastTimer;function toast(message){let el=document.querySelector('#global-toast');if(!el){el=document.createElement('p');el.id='global-toast';el.className='global-toast';el.setAttribute('role','status');document.body.append(el)}clearTimeout(toastTimer);el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,3500)}

const removeThemePicker=mountThemePicker(document.querySelector('.header-actions'));
const techReels=mountTechReels({context:'portfolio',study:{title:document.title,page}});
window.addEventListener('pagehide',()=>{techReels.dispose();removeThemePicker()},{once:true});
window.addEventListener('pageshow',event=>{if(event.persisted)location.reload()});

initializeAnalytics();
